#!/bin/sh
# Print the three most frequent IP addresses in access.log,
# breaking ties by first appearance in the log.
awk '{
    count[$1]++
    if (!($1 in first_seen)) {
        first_seen[$1] = NR
    }
}
END {
    for (ip in count) {
        print count[ip], first_seen[ip], ip
    }
}' access.log |
sort -k1,1nr -k2,2n |
head -n 3 |
awk '{ print $3 }'
